// ファイル情報の検証と前処理
const fileInfo = $input.all()[0].json;

// サポートされる音声ファイル形式をチェック
const supportedFormats = ['.wav', '.mp3', '.m4a', '.flac', '.ogg'];
const fileName = fileInfo.name.toLowerCase();
const isAudioFile = supportedFormats.some(format => fileName.endsWith(format));

if (!isAudioFile) {
  throw new Error(`サポートされていないファイル形式: ${fileName}`);
}

// ファイルサイズチェック (100MB制限)
const maxSize = 100 * 1024 * 1024; // 100MB in bytes
if (fileInfo.size > maxSize) {
  throw new Error(`ファイルサイズが制限を超えています: ${fileInfo.size} bytes`);
}

// IS担当者名をファイル名から抽出（例: "IS_田中_20240806_001.wav")
let staffName = '不明';
const staffMatch = fileName.match(/is[_-]([^_-]+)[_-]/i);
if (staffMatch) {
  staffName = staffMatch[1];
}

// 処理用データを準備
const processData = {
  fileId: fileInfo.id,
  fileName: fileInfo.name,
  fileSize: fileInfo.size,
  staffName: staffName,
  uploadTime: fileInfo.createdTime,
  downloadUrl: fileInfo.webContentLink,
  mimeType: fileInfo.mimeType
};

return processData;

// 音声認識結果の前処理
const whisperResult = $input.all()[0].json;
const fileInfo = $('ファイル検証・前処理').all()[0].json;

// 認識されたテキストを取得
const transcriptionText = whisperResult.text || '';

if (!transcriptionText.trim()) {
  throw new Error('音声認識に失敗しました。テキストが空です。');
}

// 録音時間を計算
const duration = whisperResult.duration || 0;
const durationMinutes = Math.floor(duration / 60);
const durationSeconds = Math.floor(duration % 60);
const durationFormatted = `${durationMinutes}:${durationSeconds.toString().padStart(2, '0')}`;

// OpenAI分析用のデータを準備
const analysisData = {
  fileName: fileInfo.fileName,
  staffName: fileInfo.staffName,
  uploadTime: fileInfo.uploadTime,
  transcription: transcriptionText,
  duration: durationFormatted,
  durationSeconds: duration
};

return analysisData;

